<template><div class="page"><div class="toolbar"><el-input v-model="code" placeholder="输入核销码" @keyup.enter="verifyReservation"/><el-button type="primary" :loading="verifying" @click="verifyReservation">预约签到</el-button><el-button type="success" :loading="verifying" @click="verifyMember">会员码核销</el-button><el-button @click="load">刷新记录</el-button></div><el-table :data="rows" v-loading="loading" empty-text="暂无预约核销记录"><el-table-column prop="reservationNo" label="预约单号" min-width="180"/><el-table-column prop="verifyCode" label="核销码"/><el-table-column prop="nickname" label="会员"/><el-table-column prop="seatCode" label="座位"/><el-table-column label="时段"><template #default="s">{{s.row.startTime}}-{{s.row.endTime}}</template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column prop="checkinTime" label="签到时间" min-width="160"/></el-table></div></template>
<script setup>import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{getXyVerificationRecords,verifyXyReservation,verifyXyMember}from'@/api/xy';const rows=ref([]),loading=ref(false),verifying=ref(false),code=ref('');async function load(){loading.value=true;try{rows.value=await getXyVerificationRecords()}finally{loading.value=false}}async function run(fn,message){if(!code.value)return;verifying.value=true;try{await fn(code.value);ElMessage.success(message);code.value='';load()}finally{verifying.value=false}}const verifyReservation=()=>run(verifyXyReservation,'预约签到成功');const verifyMember=()=>run(verifyXyMember,'会员核销成功');onMounted(load)</script><style scoped>.page{padding:20px;background:#fff;border-radius:16px}.toolbar{display:flex;gap:12px;margin-bottom:16px}.toolbar .el-input{max-width:300px}</style>
